const MONTHS={1:"Jan",2:"Feb",3:"Mar",4:"Apr",5:"May",6:"Jun",7:"Jul",8:"Aug"};
const norm=s=>String(s??"").trim().toLowerCase();
const num=x=>Number(x||0);
function mergedFilters(base={},o={}){
  const f={...base};
  for(const [k,v] of Object.entries(o||{})) if(v!==undefined&&v!==null&&v!==""&&v!=="all") f[k]=v;
  return f;
}
function filteredRows(baseFilters={},overrides={}){
  const f=mergedFilters(baseFilters,overrides);
  return DATA.filter(r=>{
    if(f.distributor && f.distributor!=="all" && norm(r[0])!==norm(f.distributor))return false;
    if(f.month && f.month!=="all" && Number(r[3])!==Number(f.month))return false;
    if(f.line!==undefined && f.line!=="all" && String(Number(r[4]))!==String(Number(f.line)))return false;
    if(f.segment && f.segment!=="all" && norm(r[5])!==norm(f.segment))return false;
    if(f.pattern && f.pattern!=="all" && norm(r[6])!==norm(f.pattern))return false;
    if(f.status && f.status!=="all" && norm(r[2])!==norm(f.status))return false;
    if(f.ad && f.ad!=="all" && !norm(r[1]).includes(norm(f.ad)))return false;
    if(f.ad_contains && !norm(r[1]).includes(norm(f.ad_contains)))return false;
    return true;
  });
}
function aggregate(rows,keyFn){
  const m=new Map();
  for(const r of rows){
    const k=keyFn(r); if(!m.has(k))m.set(k,{qty:0,sales:0,rows:0});
    const x=m.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);x.rows++;
  }
  return m;
}
function summary(rows){
  return {qty:rows.reduce((s,r)=>s+num(r[7]),0),sales:rows.reduce((s,r)=>s+num(r[8]),0),unique_ad:new Set(rows.map(r=>r[0]+"\u0001"+r[1])).size,rows:rows.length};
}
function topSegmentPattern(rows){
  const seg=aggregate(rows,r=>r[5]); const pat=aggregate(rows,r=>r[6]);
  const s=[...seg].sort((a,b)=>b[1].sales-a[1].sales)[0]; const p=[...pat].sort((a,b)=>b[1].sales-a[1].sales)[0];
  return {top_segment:s?.[0]||null,top_pattern:p?.[0]||null};
}
function salesSummary(args,base){
  const rows=filteredRows(base,args.filters||{}); const s=summary(rows);
  const months=[...aggregate(rows,r=>r[3])].map(([m,x])=>({month:Number(m),label:MONTHS[m],qty:x.qty,sales:x.sales})).sort((a,b)=>a.month-b.month);
  const dists=[...aggregate(rows,r=>r[0])].map(([name,x])=>({distributor:name,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales);
  const segments=[...aggregate(rows,r=>r[5])].map(([name,x])=>({segment:name,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales);
  return {...s,months,distributors:dists,segments};
}
function rankAds(args,base){
  const rows=filteredRows(base,args.filters||{}); const metric=args.metric==="qty"?"qty":"sales"; const limit=Math.min(Math.max(Number(args.limit)||10,1),50);
  const by=new Map();
  for(const r of rows){const k=r[0]+"\u0001"+r[1];if(!by.has(k))by.set(k,{distributor:r[0],ad:r[1],qty:0,sales:0,rows:[]});const x=by.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);x.rows.push(r);}
  return [...by.values()].map(x=>({...x,...topSegmentPattern(x.rows)})).sort((a,b)=>b[metric]-a[metric]).slice(0,limit).map(({rows,...x})=>x);
}
function rankPatterns(args,base){
  const rows=filteredRows(base,args.filters||{});const metric=args.metric==="qty"?"qty":"sales";const limit=Math.min(Math.max(Number(args.limit)||10,1),50);
  const by=new Map();for(const r of rows){const k=r[6];if(!by.has(k))by.set(k,{pattern:k,segment:r[5],qty:0,sales:0});const x=by.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);}
  return [...by.values()].sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}
function monthlyTrend(args,base){
  const rows=filteredRows(base,{...(args.filters||{}),month:"all"}); const by=aggregate(rows,r=>r[3]);
  return [...by].map(([m,x])=>({month:Number(m),label:MONTHS[m],qty:x.qty,sales:x.sales})).sort((a,b)=>a.month-b.month);
}
function compareMonths(args,base){
  const ma=Number(args.month_a),mb=Number(args.month_b); const metric=args.metric==="qty"?"qty":"sales"; const group=args.group_by||"ad"; const limit=Math.min(Math.max(Number(args.limit)||15,1),50);
  const baseF={...(args.filters||{}),month:"all"}; const rows=filteredRows(base,baseF);
  const keyFn=r=>group==="pattern"?r[6]:group==="distributor"?r[0]:group==="segment"?r[5]:(r[0]+"\u0001"+r[1]);
  const a=aggregate(rows.filter(r=>Number(r[3])===ma),keyFn), b=aggregate(rows.filter(r=>Number(r[3])===mb),keyFn);
  const keys=new Set([...a.keys(),...b.keys()]); const out=[];
  for(const k of keys){const av=a.get(k)?.[metric]||0,bv=b.get(k)?.[metric]||0; const delta=bv-av; const pct=av?delta/av*100:(bv?null:0); let label=k,dist=null;if(group==="ad"){[dist,label]=k.split("\u0001");}
    out.push({label,distributor:dist,month_a:ma,value_a:av,month_b:mb,value_b:bv,delta,pct_change:pct});}
  const direction=args.direction||"decline"; out.sort((x,y)=>direction==="growth"?y.delta-x.delta:x.delta-y.delta); return out.slice(0,limit);
}
function bigRetail(args,base){
  const rows=filteredRows(base,{...(args.filters||{}),status:"Big Retail"}); const s=summary(rows); const seg=[...aggregate(rows,r=>r[5])].map(([segment,x])=>({segment,qty:x.qty,sales:x.sales,sales_pct:s.sales?x.sales/s.sales*100:0,qty_pct:s.qty?x.qty/s.qty*100:0})).sort((a,b)=>b.sales-a.sales);
  return {...s,segments:seg,top_ads:rankAds({filters:{...(args.filters||{}),status:"Big Retail"},metric:args.metric||"sales",limit:args.limit||15},base)};
}
function storeDetail(args,base){
  const q=args.name||""; const rows=filteredRows(base,{...(args.filters||{}),month:"all",ad_contains:q});
  const byStore=new Map(); for(const r of rows){const k=r[0]+"\u0001"+r[1];if(!byStore.has(k))byStore.set(k,[]);byStore.get(k).push(r);}
  return [...byStore].slice(0,8).map(([k,rs])=>{const [dist,ad]=k.split("\u0001");const s=summary(rs);return {distributor:dist,ad,...s,monthly:[...aggregate(rs,r=>r[3])].map(([m,x])=>({month:Number(m),label:MONTHS[m],qty:x.qty,sales:x.sales})).sort((a,b)=>a.month-b.month),segments:[...aggregate(rs,r=>r[5])].map(([segment,x])=>({segment,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales),patterns:[...aggregate(rs,r=>r[6])].map(([pattern,x])=>({pattern,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales).slice(0,20)};});
}
function registrationSummary(args,base){
  const f={...(args.filters||{})};
  f.line="all";
  const rows=filteredRows(base,f);
  const yes=rows.filter(r=>Number(r[4])===1), no=rows.filter(r=>Number(r[4])!==1);

  const byStore=new Map();
  for(const r of rows){
    const k=r[0]+"\u0001"+r[1];
    if(!byStore.has(k))byStore.set(k,{distributor:r[0],ad:r[1],qty:0,sales:0,line_registered:false});
    const x=byStore.get(k);
    x.qty+=num(r[7]); x.sales+=num(r[8]);
    if(Number(r[4])===1)x.line_registered=true;
  }
  const stores=[...byStore.values()];
  const registeredStores=stores.filter(x=>x.line_registered);
  const notRegisteredStores=stores.filter(x=>!x.line_registered);

  return {
    store_count:stores.length,
    registered_store_count:registeredStores.length,
    not_registered_store_count:notRegisteredStores.length,
    registered:summary(yes),
    not_registered:summary(no),
    top_not_registered:notRegisteredStores.sort((a,b)=>b.sales-a.sales).slice(0,20),
    top_registered:registeredStores.sort((a,b)=>b.sales-a.sales).slice(0,20)
  };
}
function percentileMedian(a){const x=a.filter(Number.isFinite).sort((a,b)=>a-b);if(!x.length)return 0;const m=Math.floor(x.length/2);return x.length%2?x[m]:(x[m-1]+x[m])/2;}
function sizeTier(q){q=Number(q||0);if(q<500)return null;if(q<1500)return {key:"small",label:"Small",range:"500-1,499"};if(q<5000)return {key:"medium",label:"Medium",range:"1,500-4,999"};return {key:"large",label:"Large",range:"5,000+"};}
function selfStore(name,dist){const n=norm(name),d=norm(dist);if(n.includes("หน้าร้าน"))return true;if(d==="epb"&&(n.includes("เอกไพบูลย์")||n.includes("ekpaiboon")))return true;if(d==="nky"&&(n.includes("นครยาง")||n.includes("n.yang")))return true;if(d==="sompol"&&n.includes("สมพล"))return true;if(d==="mgp"&&(n.includes("my megapart")||n.includes("เมกาพาร์ท")))return true;if(d==="rty"&&(n.includes("rty")||n.includes("ราชา")))return true;return false;}
function caiOpportunities(args,base){
  const all=filteredRows(base,{month:"all",line:"all",segment:"all",pattern:"all",ad:"all"}); const totalQty=aggregate(all,r=>r[0]+"\u0001"+r[1]);
  const filter=args.filters||{}; const limit=Math.min(Math.max(Number(args.limit)||15,1),40); const out=[];
  for(const g of CAI_PAIR_GROUPS){if(filter.segment&&filter.segment!=="all"&&norm(g.segment)!==norm(filter.segment))continue;if(filter.pattern&&filter.pattern!=="all"&&norm(g.pattern)!==norm(filter.pattern))continue;
    const peers=(g.dealers||[]).filter(d=>!selfStore(d.name,d.dist));
    for(const d of peers){if(filter.distributor&&filter.distributor!=="all"&&norm(d.dist)!==norm(filter.distributor))continue;if(filter.ad&&filter.ad!=="all"&&!norm(d.name).includes(norm(filter.ad)))continue;const dk=d.dist+"\u0001"+d.name;const tq=totalQty.get(dk)?.qty||0;const tier=sizeTier(tq);if(!tier)continue;const mix=num(d.totalQty)/tq*100;
      const same=peers.filter(p=>!(p.dist===d.dist&&p.name===d.name)).map(p=>{const pk=p.dist+"\u0001"+p.name;const q=totalQty.get(pk)?.qty||0;return {p,q,t:sizeTier(q)};}).filter(x=>x.t?.key===tier.key&&x.q>0);if(same.length<2)continue;const peerMix=percentileMedian(same.map(x=>num(x.p.totalQty)/x.q*100));if(peerMix<=mix)continue;const benchmark=tq*peerMix/100,gap=benchmark-num(d.totalQty);if(gap<4)continue;out.push({distributor:d.dist,ad:d.name,size_tier:tier.label,ytd_qty:tq,pattern:g.pattern,segment:g.segment,front:g.frontSize,rear:g.rearSize,current_pair_qty:num(d.totalQty),current_mix_pct:mix,peer_count:same.length,peer_mix_pct:peerMix,benchmark_qty:benchmark,gap_qty:gap,vehicle:(g.topModels||[])[0]||null});}
  }
  return out.sort((a,b)=>b.gap_qty-a.gap_qty).slice(0,limit);
}
function missionSummary(args){
  if(!MISSION_DATA.length)return {available:false}; let rows=MISSION_DATA; const f=args.filters||{}; if(f.distributor&&f.distributor!=="all")rows=rows.filter(x=>norm(x.distributor)===norm(f.distributor)); if(f.search)rows=rows.filter(x=>norm([x.storeName,x.selloutADName,x.adCode].join(" ")).includes(norm(f.search)));
  return {available:true,stores:rows.length,registered:rows.filter(x=>x.missionRegistered).length,not_registered:rows.filter(x=>!x.missionRegistered).length,matched:rows.filter(x=>x.matchBy!=="Not matched").length,top_not_registered:rows.filter(x=>!x.missionRegistered&&x.matchBy!=="Not matched").sort((a,b)=>num(b.ytdValue)-num(a.ytdValue)).slice(0,20).map(x=>({distributor:x.distributor,ad_code:x.adCode,store:x.selloutADName||x.storeName,ytd_value:x.ytdValue,ytd_qty:x.ytdQty,line_registered:x.lineRegistered,size:x.sizeTier}))};
}


const toolDefs=[
 {type:"function",name:"sales_summary",description:"Get exact sales, quantity, AD count, monthly, distributor and segment summary under filters.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true}},additionalProperties:false}},
 {type:"function",name:"rank_ads",description:"Rank AD stores by sales value or tyre quantity under filters.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true},metric:{type:"string",enum:["sales","qty"]},limit:{type:"integer"}},required:["metric","limit"],additionalProperties:false}},
 {type:"function",name:"rank_patterns",description:"Rank tyre patterns by sales value or quantity.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true},metric:{type:"string",enum:["sales","qty"]},limit:{type:"integer"}},required:["metric","limit"],additionalProperties:false}},
 {type:"function",name:"monthly_trend",description:"Get Jan-Aug monthly trend for the selected scope.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true}},additionalProperties:false}},
 {type:"function",name:"compare_months",description:"Compare two months by AD, pattern, distributor or segment and rank decline/growth.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true},month_a:{type:"integer",minimum:1,maximum:8},month_b:{type:"integer",minimum:1,maximum:8},group_by:{type:"string",enum:["ad","pattern","distributor","segment"]},metric:{type:"string",enum:["sales","qty"]},direction:{type:"string",enum:["decline","growth"]},limit:{type:"integer"}},required:["month_a","month_b","group_by","metric","direction","limit"],additionalProperties:false}},
 {type:"function",name:"big_retail_summary",description:"Analyze only Big Retail stores, including segment mix and top Big Retail ADs.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true},metric:{type:"string",enum:["sales","qty"]},limit:{type:"integer"}},required:["metric","limit"],additionalProperties:false}},
 {type:"function",name:"store_detail",description:"Find store(s) by partial name and return monthly, segment and pattern detail.",parameters:{type:"object",properties:{name:{type:"string"},filters:{type:"object",additionalProperties:true}},required:["name"],additionalProperties:false}},
 {type:"function",name:"registration_summary",description:"LINE OA / Line Register status only. Use this for questions about Line registration, LINE OA registration, registered vs not registered stores, or which unregistered stores have high sales. Returns unique store counts plus top unregistered stores by sales. NEVER use Mission registration as a substitute.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true}},additionalProperties:false}},
 {type:"function",name:"cai_opportunities",description:"Get exact CAI pair opportunities using dashboard size tiers: Small 500-1499, Medium 1500-4999, Large 5000+, cross-distributor peer median, excluding AD below 500 tyres.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true},limit:{type:"integer"}},required:["limit"],additionalProperties:false}},
 {type:"function",name:"mission_summary",description:"MISSION registration only (Join Mission / Mission campaign). Use ONLY when the user explicitly asks about Mission or Join Mission. Mission registration is different from LINE OA / Line Register.",parameters:{type:"object",properties:{filters:{type:"object",additionalProperties:true}},additionalProperties:false}}
];
function runTool(name,args,base){switch(name){case"sales_summary":return salesSummary(args,base);case"rank_ads":return rankAds(args,base);case"rank_patterns":return rankPatterns(args,base);case"monthly_trend":return monthlyTrend(args,base);case"compare_months":return compareMonths(args,base);case"big_retail_summary":return bigRetail(args,base);case"store_detail":return storeDetail(args,base);case"registration_summary":return registrationSummary(args,base);case"cai_opportunities":return caiOpportunities(args,base);case"mission_summary":return missionSummary(args);default:return {error:"Unknown tool"};}}



function makeVisualization(toolName,result,args,question){
  const q=norm(question||"");
  const wantsQty=/qty|quantity|จำนวน|เส้น/.test(q);
  const wantsSales=/sales|value|ยอดขาย|บาท|มูลค่า/.test(q);
  const format=wantsQty&&!wantsSales?"number":"currency";

  if(toolName==="big_retail_summary" && result?.segments?.length){
    const metric=(wantsQty&&!wantsSales)?"qty":"sales";
    const pctKey=metric==="qty"?"qty_pct":"sales_pct";
    return {
      type:"donut",
      title:`Big Retail ${metric==="qty"?"Quantity":"Sales"} Mix by Segment`,
      subtitle:"Calculated directly from dashboard data",
      format:metric==="qty"?"number":"currency",
      center_label:metric==="qty"?"Quantity mix":"Sales mix",
      items:result.segments.map(x=>({label:x.segment,value:Number(x[metric]||0),pct:Number(x[pctKey]||0)}))
    };
  }

  if(toolName==="sales_summary"){
    if(result?.segments?.length){
      const metric=(wantsQty&&!wantsSales)?"qty":"sales";
      return {
        type:"donut",title:`${metric==="qty"?"Quantity":"Sales"} Mix by Segment`,
        subtitle:"Current dashboard scope",format:metric==="qty"?"number":"currency",
        items:result.segments.map(x=>({label:x.segment,value:Number(x[metric]||0)}))
      };
    }
  }

  if(toolName==="monthly_trend" && Array.isArray(result)){
    const metric=(wantsQty&&!wantsSales)?"qty":"sales";
    return {
      type:"line",title:`Monthly ${metric==="qty"?"Quantity":"Sales"} Trend`,
      subtitle:"Jan–Aug 2026",format:metric==="qty"?"number":"currency",
      items:result.map(x=>({label:x.label,value:Number(x[metric]||0)}))
    };
  }

  if(toolName==="rank_ads" && Array.isArray(result)){
    const metric=args?.metric==="qty"?"qty":"sales";
    return {
      type:"bar",title:`Top AD by ${metric==="qty"?"Quantity":"Sales"}`,
      format:metric==="qty"?"number":"currency",
      items:result.slice(0,10).map(x=>({label:x.ad,value:Number(x[metric]||0)}))
    };
  }

  if(toolName==="rank_patterns" && Array.isArray(result)){
    const metric=args?.metric==="qty"?"qty":"sales";
    return {
      type:"bar",title:`Top Patterns by ${metric==="qty"?"Quantity":"Sales"}`,
      format:metric==="qty"?"number":"currency",
      items:result.slice(0,10).map(x=>({label:x.pattern,value:Number(x[metric]||0)}))
    };
  }

  if(toolName==="compare_months" && Array.isArray(result)){
    return {
      type:"bar",title:"Largest Changes",
      subtitle:"Absolute change between selected months",
      format:args?.metric==="qty"?"number":"currency",
      items:result.slice(0,10).map(x=>({label:x.label,value:Math.abs(Number(x.delta||0))}))
    };
  }

  if(toolName==="registration_summary" && result?.registered && result?.not_registered){
    const asksStores=/ร้าน|store|dealer|ad\b|กี่ราย|กี่ร้าน|ลงทะเบียน/.test(q);
    if(asksStores && Number.isFinite(Number(result.registered_store_count))){
      const a=Number(result.registered_store_count||0),b=Number(result.not_registered_store_count||0),t=a+b;
      return {
        type:"donut",title:"LINE OA Registration by Store",format:"number",
        items:[
          {label:"Registered",value:a,pct:t?a/t*100:0},
          {label:"Not registered",value:b,pct:t?b/t*100:0}
        ]
      };
    }
    const metric=(wantsQty&&!wantsSales)?"qty":"sales";
    const a=Number(result.registered[metric]||0),b=Number(result.not_registered[metric]||0),t=a+b;
    return {
      type:"donut",title:`LINE OA Registration ${metric==="qty"?"Quantity":"Sales"} Mix`,
      format:metric==="qty"?"number":"currency",
      items:[
        {label:"Registered",value:a,pct:t?a/t*100:0},
        {label:"Not registered",value:b,pct:t?b/t*100:0}
      ]
    };
  }

  if(toolName==="store_detail" && Array.isArray(result) && result.length===1 && result[0]?.monthly?.length){
    const metric=(wantsQty&&!wantsSales)?"qty":"sales";
    return {
      type:"line",title:`${result[0].ad} · Monthly ${metric==="qty"?"Quantity":"Sales"}`,
      subtitle:result[0].distributor||"",format:metric==="qty"?"number":"currency",
      items:result[0].monthly.map(x=>({label:x.label,value:Number(x[metric]||0)}))
    };
  }

  if(toolName==="cai_opportunities" && Array.isArray(result) && result.length){
    return {
      type:"bar",title:"Top CAI Opportunity Gaps",
      subtitle:"Gap to same-size peer benchmark · tyres",format:"number",
      items:result.slice(0,10).map(x=>({label:`${x.ad} · ${x.pattern}`,value:Number(x.gap_qty||0)}))
    };
  }

  if(toolName==="mission_summary" && result?.available){
    return {
      type:"donut",title:"Mission Registration Mix",format:"number",
      items:[
        {label:"Registered",value:Number(result.registered||0)},
        {label:"Not registered",value:Number(result.not_registered||0)}
      ]
    };
  }

  return null;
}

const SYSTEM=`You are the AI Sales Analyst inside Michelin Thailand's two-wheel sell-out dashboard. Data period is Jan-Aug 2026 unless a tool says otherwise. Answer in Thai when the user asks in Thai, otherwise in the user's language. Be concise and business-useful. Use calculation tools for every numeric claim; never invent numbers. Current dashboard filters are the default scope unless the user explicitly overrides them. Distinguish Sales Value (THB) from Quantity (tyres). Month mapping: 1 Jan, 2 Feb, 3 Mar, 4 Apr, 5 May, 6 Jun, 7 Jul, 8 Aug. Use compare_months for MoM, store_detail for a named store, big_retail_summary for Big Retail, and cai_opportunities for CAI/Opportunity. Mention Jan-Aug limitation when relevant. Do not claim causation from sales data alone. Keep the answer short because the dashboard may render a chart automatically; do not describe how to draw a chart and do not output chart JSON. Registration terminology is strict: when the user says 'Line register', 'LINE register', 'LINE OA', 'ลงทะเบียน Line', or asks which stores have not registered Line, ALWAYS call registration_summary. When the user says 'Mission' or 'Join Mission', use mission_summary. NEVER infer that Mission not-registered means Line not-registered, and never label Mission registration as Line registration. For a request such as 'ร้านไหนยังไม่ได้ลงทะเบียน Line แล้วมียอดซื้อเยอะ', call registration_summary and use top_not_registered.`;



const te=new TextEncoder();
function escHtml(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function cookieMap(request){
  const raw=request.headers.get("Cookie")||""; const out={};
  for(const part of raw.split(";")){const p=part.trim();if(!p)continue;const i=p.indexOf("=");if(i>0)out[decodeURIComponent(p.slice(0,i))]=decodeURIComponent(p.slice(i+1));}
  return out;
}
async function hmac(text,secret){
  const key=await crypto.subtle.importKey("raw",te.encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);
  const sig=new Uint8Array(await crypto.subtle.sign("HMAC",key,te.encode(text)));
  let b="";for(const x of sig)b+=String.fromCharCode(x);return btoa(b).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
}
async function makeSession(secret){const exp=Date.now()+12*60*60*1000;return `${exp}.${await hmac(String(exp),secret)}`;}
async function isAuthed(request,env){
  if(!env.DASHBOARD_PASSWORD)return true;
  const token=cookieMap(request).dashboard_session;if(!token)return false;
  const [exp,sig]=token.split(".");if(!exp||!sig||Number(exp)<Date.now())return false;
  return sig===await hmac(exp,env.DASHBOARD_PASSWORD);
}
function loginPage(error=""){return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard Access</title><style>body{margin:0;font-family:Arial,sans-serif;background:#f4f6f9;display:grid;place-items:center;min-height:100vh;color:#172b4d}.card{width:min(390px,90vw);background:#fff;border:1px solid #dce3eb;border-radius:16px;padding:28px;box-shadow:0 16px 45px rgba(20,43,75,.12)}.e{font-size:11px;font-weight:900;letter-spacing:.08em;color:#173d76}.t{font-size:25px;font-weight:900;margin:7px 0 5px;color:#173d76}.s{font-size:13px;color:#6b778c;line-height:1.5}input{width:100%;box-sizing:border-box;height:43px;margin-top:18px;border:1px solid #ccd5df;border-radius:9px;padding:0 12px;font-size:15px}button{width:100%;height:43px;margin-top:10px;border:0;border-radius:9px;background:#173d76;color:#fff;font-weight:800;cursor:pointer}.err{margin-top:9px;color:#b3261e;font-size:12px;min-height:16px}</style></head><body><form class="card" method="post" action="/login"><div class="e">MICHELIN THAILAND · TWO-WHEEL</div><div class="t">Dashboard Access</div><div class="s">Enter the shared password to continue.</div><input name="password" type="password" autocomplete="current-password" autofocus placeholder="Password"><button>Open Dashboard</button><div class="err">${escHtml(error)}</div></form></body></html>`;}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}});}
function extractOutputText(resp){
  const chunks=[];for(const item of resp?.output||[])if(item.type==="message")for(const c of item.content||[])if(c.type==="output_text"&&c.text)chunks.push(c.text);return chunks.join("\n").trim();
}
async function openAI(env,payload){
  const r=await fetch("https://api.openai.com/v1/responses",{method:"POST",headers:{"Authorization":`Bearer ${env.OPENAI_API_KEY}`,"Content-Type":"application/json"},body:JSON.stringify(payload)});
  const body=await r.json().catch(()=>({}));
  if(!r.ok){const msg=body?.error?.message||`OpenAI API error ${r.status}`;const e=new Error(msg);e.status=r.status;throw e;}
  return body;
}
async function handleAsk(request,env){
  if(!env.OPENAI_API_KEY)return json({error:"OPENAI_API_KEY is not configured in Netlify Environment Variables."},503);
  const body=await request.json().catch(()=>({}));
  const question=String(body?.question||"").trim();
  if(!question)return json({error:"Question is required."},400);

  const baseFilters=body?.filters||{};
  const history=Array.isArray(body?.history)?body.history.slice(-6):[];
  const hist=history
    .filter(x=>x&&["user","assistant"].includes(x.role)&&typeof x.content==="string")
    .slice(0,-1)
    .map(x=>({role:x.role,content:x.content.slice(0,2500)}));

  let input=[...hist,{role:"user",content:`Filters: ${JSON.stringify(baseFilters)}\nQuestion: ${question}`}];
  const model=env.OPENAI_MODEL||"gpt-5.4-mini";
  const requestCfg={model,instructions:SYSTEM,input,tools:toolDefs,tool_choice:"auto",store:false,reasoning:{effort:"low"},max_output_tokens:1000};

  let response=await openAI(env,requestCfg);
  let lastTool=null;

  for(let step=0;step<5;step++){
    const calls=(response.output||[]).filter(x=>x.type==="function_call");
    if(!calls.length)break;

    input.push(...response.output);
    for(const call of calls){
      let args={};
      try{args=JSON.parse(call.arguments||"{}");}catch{}
      const result=runTool(call.name,args,baseFilters);
      lastTool={name:call.name,args,result};
      input.push({type:"function_call_output",call_id:call.call_id,output:JSON.stringify(result)});
    }
    response=await openAI(env,{...requestCfg,input});
  }

  const answer=extractOutputText(response);
  if(!answer)return json({error:"AI returned no text response."},500);

  // Visualization is built deterministically from the calculation-tool result.
  // It costs ZERO additional OpenAI tokens.
  const visualization=lastTool
    ? makeVisualization(lastTool.name,lastTool.result,lastTool.args,question)
    : null;

  return json({answer,model,visualization});
}

function authOK(request){
  const required=process.env.DASHBOARD_PASSWORD||"";
  if(!required)return true;
  return (request.headers.get("X-Dashboard-Password")||"")===required;
}

export default async (request, context) => {
  if(!authOK(request)){
    return json({error:"Incorrect dashboard password."},401);
  }

  const url=new URL(request.url);
  const action=url.searchParams.get("action")||"";

  if(request.method==="GET" && action==="health"){
    return json({
      ok:!!process.env.OPENAI_API_KEY,
      model:process.env.OPENAI_MODEL||"gpt-5.4-mini",
      data_rows:DATA.length,
      cai_groups:CAI_PAIR_GROUPS.length
    });
  }

  if(request.method==="POST"){
    try{
      return await handleAsk(request,process.env);
    }catch(err){
      const status=err?.status&&err.status<600?err.status:500;
      const msg=err?.status===429
        ?"OpenAI rate/credit limit reached."
        :(err?.message||"AI request failed");
      return json({error:msg},status);
    }
  }

  return json({error:"Not found"},404);
};
